209  std::optional<component::MAC> OpHMAC_HMAC(operation::HMAC& op, Datasource& ds) {
   210      std::optional<component::MAC> ret = std::nullopt;
   211
   212      util::Multipart parts;
   213
   214      CF_HMAC_CTX ctx(ds);
   215      const EVP_MD* md = nullptr;
   216
   217      /* Initialize */
   218      {
   219          parts = util::ToParts(ds, op.cleartext);
   220          /* TODO remove ? */
   221          HMAC_CTX_reset(ctx.GetPtr());
   222          CF_CHECK_NE(md = toEVPMD(op.digestType), nullptr);
   223          CF_CHECK_EQ(HMAC_Init_ex(ctx.GetPtr(), op.cipher.key.GetPtr(), op.cipher.key.GetSize(), md, nullptr), 1);
   224      }
   225
   226      /* Process */
   227      for (const auto& part : parts) {
   228          CF_CHECK_EQ(HMAC_Update(ctx.GetPtr(), part.first, part.second), 1);
   229      }
   230
   231      /* Finalize */
   232      {
   233          unsigned int len = -1;
   234          uint8_t out[EVP_MAX_MD_SIZE];
   235          CF_CHECK_EQ(HMAC_Final(ctx.GetPtr(), out, &len), 1);
   236
   237          ret = component::MAC(out, len);
   238      }
   239
   240  end:
   241      return ret;
   242  }
   243  }
